use vstd::prelude::*;

verus! {

// Specification function to count eligible participants
spec fn count_eligible(participations: Seq<int>, k: int) -> int
    decreases participations.len(),
{
    if participations.len() == 0 {
        0
    } else {
        let first = participations[0];
        let rest_count = count_eligible(participations.subrange(1, participations.len() as int), k);
        if 5 - first >= k {
            1 + rest_count
        } else {
            rest_count
        }
    }
}

// Helper specification: count eligible participants in first n elements
spec fn count_eligible_n(participations: Seq<int>, n: int, k: int) -> int
    decreases n,
{
    if n <= 0 || participations.len() == 0 {
        0
    } else if n > participations.len() {
        count_eligible(participations, k)
    } else {
        count_eligible(participations.subrange(0, n), k)
    }
}

fn solve(n: u8, k: u8, participations: Vec<u8>) -> (result: u8)
    requires
        k <= 5,
        forall|i: int| 0 <= i < participations.len() ==> participations[i] <= 5,
    ensures
        result == count_eligible_n(participations@, n as int, k as int) / 3,
{
    let mut count: u8 = 0;
    let mut i: u8 = 0;

    while i < n && (i as int) < participations.len() as int
        invariant
            i <= n,
            i as int <= participations.len() as int,
            count as int == count_eligible_n(participations@, i as int, k as int) / 3,
            k <= 5,
            forall|j: int| 0 <= j < participations.len() as int ==> participations[j as usize] <= 5,
        decreases n - i,
    {
        let p = participations[i as usize];
        if 5 - (p as int) >= k as int {
            count += 1;
        }
        i += 1;
    }

    // Integer division by 3 to get the result
    count / 3
}

} 

